package blockchain.contracts

import scala.concurrent.{Future, ExecutionContext}
import scala.collection.mutable
import scala.util.{Success, Failure}

object ContractRegistry {
  implicit val ec: ExecutionContext = ExecutionContext.global

  // Base prototype for contract state - shared template (immutable reference)
  private val basePrototype: Map[String, Any] = Map(
    "owner" -> "0x0000000000000000000000000000000000000000",
    "balance" -> BigInt(0),
    "isActive" -> true,
    "permissions" -> Map("admin" -> true, "transfer" -> false)
  )

  // Contract instances get a deep copy of defaults, no shared mutable state
  case class ContractState(
    address: String,
    localState: mutable.Map[String, Any] = mutable.Map.empty
  ) {
    def get(key: String): Any = {
      localState.getOrElse(key, basePrototype.getOrElse(key, null))
    }

    def set(key: String, value: Any): Unit = {
      localState(key) = value
    }

    // Ensure mutable copy exists in localState before modification
    def getLocalMutable(key: String): Any = {
      if (!localState.contains(key)) {
        // Deep copy from prototype into local state
        basePrototype.get(key) match {
          case Some(m: Map[String @unchecked, Any @unchecked]) =>
            localState(key) = mutable.Map(m.toSeq: _*)
          case Some(v) =>
            localState(key) = v
          case None => // nothing
        }
      }
      localState.getOrElse(key, null)
    }
  }

  private val contracts: mutable.Map[String, ContractState] = mutable.Map.empty
  private val pendingTransactions: mutable.Queue[(String, Map[String, Any])] = mutable.Queue.empty

  def deployContract(address: String, initialState: Map[String, Any]): Future[ContractState] = Future {
    val contract = ContractState(address)
    initialState.foreach { case (k, v) => contract.set(k, v) }
    contracts(address) = contract
    contract
  }

  def executeTransaction(callerAddress: String, contractAddress: String, 
                         method: String, params: Map[String, Any]): Future[Any] = Future {
    val contract = contracts.getOrElse(contractAddress, 
      throw new RuntimeException(s"Contract $contractAddress not found"))

    method match {
      case "transfer" =>
        validateTransfer(contract, callerAddress, params)
      case "updateState" =>
        updateContractState(contract, callerAddress, params)
      case "delegateCall" =>
        executeDelegateCall(contract, callerAddress, params)
      case _ =>
        throw new RuntimeException(s"Unknown method: $method")
    }
  }

  private def validateTransfer(contract: ContractState, caller: String, 
                                params: Map[String, Any]): Boolean = {
    val permissions = contract.get("permissions").asInstanceOf[Map[String, Boolean]]
    if (!permissions.getOrElse("transfer", false)) {
      throw new RuntimeException("Transfer not permitted")
    }
    val amount = params.getOrElse("amount", BigInt(0)).asInstanceOf[BigInt]
    val currentBalance = contract.get("balance").asInstanceOf[BigInt]
    if (amount > currentBalance) {
      throw new RuntimeException("Insufficient balance")
    }
    contract.set("balance", currentBalance - amount)
    true
  }

  // Safe: copies prototype data into local state before modification
  private def updateContractState(contract: ContractState, caller: String,
                                   params: Map[String, Any]): Boolean = {
    val owner = contract.get("owner").asInstanceOf[String]
    if (caller != owner) {
      throw new RuntimeException("Only owner can update state")
    }

    params.foreach { case (key, value) =>
      // Resolve nested keys using dot notation (e.g., "permissions.transfer")
      val parts = key.split("\\.")
      if (parts.length == 1) {
        contract.set(key, value)
      } else {
        // Navigate the chain - ensures local copy before mutation
        resolveAndSet(contract, parts, value)
      }
    }
    true
  }

  private def resolveAndSet(contract: ContractState, parts: Array[String], value: Any): Unit = {
    val rootKey = parts.head
    val remainingPath = parts.tail

    // SAFE: getLocalMutable ensures we have a local copy, not the shared prototype
    val root = contract.getLocalMutable(rootKey)

    root match {
      case m: mutable.Map[String @unchecked, Any @unchecked] =>
        var current: mutable.Map[String, Any] = m
        for (i <- 0 until remainingPath.length - 1) {
          current = current(remainingPath(i)).asInstanceOf[mutable.Map[String, Any]]
        }
        current(remainingPath.last) = value
      case _ =>
        throw new RuntimeException(s"Cannot navigate into non-map value at ${parts.head}")
    }
  }

  private def executeDelegateCall(contract: ContractState, caller: String,
                                   params: Map[String, Any]): Future[Any] = {
    val targetAddress = params.getOrElse("target", "").asInstanceOf[String]
    val targetMethod = params.getOrElse("method", "").asInstanceOf[String]
    val targetParams = params.getOrElse("params", Map.empty).asInstanceOf[Map[String, Any]]

    // Execute in context of current contract but calling target's code
    executeTransaction(caller, targetAddress, targetMethod, targetParams)
  }

  def getContractState(address: String, key: String): Any = {
    contracts.get(address).map(_.get(key)).orNull
  }

  def getBasePrototype: Map[String, Any] = basePrototype
}

// Transaction processor with async batching
class TransactionProcessor {
  import ContractRegistry._
  implicit val ec: ExecutionContext = ExecutionContext.global

  def processBatch(transactions: Seq[(String, String, String, Map[String, Any])]): Future[Seq[Any]] = {
    val futures = transactions.map { case (caller, contract, method, params) =>
      executeTransaction(caller, contract, method, params).recover {
        case e: Exception => s"Error: ${e.getMessage}"
      }
    }
    Future.sequence(futures)
  }
}
